test("bounds declared response size and rejects missing bodies", async () => {
  let cancelled = false;
  await assert.rejects(
    scoreFeedCandidate(candidate, context, "test-key", {
      fetch: async () => new Response(new ReadableStream({
        cancel() {
          cancelled = true;
        },
      }), { headers: { "content-length": "100001" } }),
    }),
    /invalid scoring response/,
  );
  assert.equal(cancelled, true);
  await assert.rejects(
    scoreFeedCandidate(candidate, context, "test-key", {
      fetch: async () => new Response(null),
    }),
    /invalid scoring response/,
  );
});

test("timeouts abort the SDK transport and cancel a stalled response body", async () => {
  let signal: AbortSignal | null | undefined;
  let cancelled = false;
  await assert.rejects(
    scoreFeedCandidate(candidate, context, "test-key", {
      timeoutMs: 10,
      fetch: async (_input, init) => {
        signal = init?.signal;
        return new Response(new ReadableStream({
          start(controller) {
            controller.enqueue(new TextEncoder().encode('{"answers":'));
          },
          cancel() {
            cancelled = true;
          },
        }));
      },
    }),
    /timed out/,
  );
  assert.equal(signal?.aborted, true);
  assert.equal(cancelled, true);
});

test("SDK environment defaults cannot redirect scoring or log private data", async (t) => {
  const overrides = {
    TYPESAFE_BASE_URL: "https://untrusted.example.com",
    TYPESAFE_DEFAULT_MODEL: "untrusted-model",
    TYPESAFE_LOG_LEVEL: "debug",
    TYPESAFE_API_KEY: "untrusted-key",
  };
  const previous = Object.fromEntries(
    Object.keys(overrides).map((key) => [key, process.env[key]]),
  );
  const logs = ["debug", "info", "warn", "error"].map((method) =>
    t.mock.method(console, method as "debug" | "info" | "warn" | "error", () => {}),
  );
  Object.assign(process.env, overrides);
  try {
    await scoreFeedCandidate(candidate, context, "test-key", {
      fetch: async (input, init) => {
        assert.equal(String(input), "https://api.typesafe.ai/v1/systemone");
        assert.equal(new Headers(init?.headers).get("authorization"), "Bearer test-key");
        assert.equal(JSON.parse(String(init?.body)).model, JEV_FEED_MODEL);
        return Response.json(responseBody());
      },
    });
    for (const log of logs) assert.equal(log.mock.callCount(), 0);
  } finally {
    for (const [key, value] of Object.entries(previous)) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
  }
});

